```python
import os
import json
import numpy as np
from scipy.optimize import minimize


def main():
    instance = json.loads(os.environ["SUB_INSTANCE_JSON"])
    block_items = instance.get("block_items") or []
    n = len(block_items) if block_items else int(instance.get("num_variables", 0))

    weights = instance.get("weights") or {}
    alpha = float(weights.get("alpha", 1.0))
    beta_w = float(weights.get("beta", 1.0))
    gamma_w = float(weights.get("gamma", 1.0))
    delta = float(weights.get("delta", 0.0))

    Q = np.zeros((n, n), dtype=float)
    c_vec = np.zeros(n, dtype=float)
    for i, item in enumerate(block_items):
        cost_i = float(item.get("cost", 0.0))
        pcount_i = float(item.get("pcount", 0.0))
        dist_i = float(item.get("dist", 0.0))
        c_i = gamma_w * cost_i - alpha * pcount_i - beta_w * dist_i + delta
        c_vec[i] = c_i
        Q[i, i] = c_i

    pauli_terms = []
    for i in range(n):
        if abs(Q[i, i]) < 1e-12:
            continue
        label = ["I"] * n
        label[i] = "Z"
        pauli_terms.append(("".join(label), float(-Q[i, i] / 2.0)))

    if not np.any(c_vec):
        bitstring = "0" * n
        print(json.dumps({
            "value": 0.0,
            "instance": {"type": "qubo", "matrix": Q.tolist(),
                         "num_variables": n, "pauli_terms": pauli_terms},
            "bitstring": bitstring,
            "num_qubits": n,
            "note": "all-zero block"
        }))
        return

    N = 1 << n
    states = np.arange(N, dtype=np.int64)
    bits = np.zeros((N, n), dtype=np.float64)
    for i in range(n):
        bits[:, i] = ((states >> (n - 1 - i)) & 1).astype(np.float64)
    C_diag = bits @ c_vec

    psi0 = np.ones(N, dtype=np.complex128)/ np.sqrt(N)

    def apply_x_mixer(psi, beta_val):
        cval = float(np.cos(beta_val))
        sval = -1j * float(np.sin(beta_val))
        state = psi.reshape([2] * n).copy()
        for q in range(n):
            idx0 = [slice(None)] * n
            idx1 = [slice(None)] * n
            idx0[q] = 0
            idx1[q] = 1
            t0 = tuple(idx0)
            t1 = tuple(idx1)
            a0 = state[t0].copy()
            a1 = state[t1].copy()
            state[t0] = cval * a0 + sval *a1
            state[t1] = sval * a0 + cval * a1
        return state.reshape(N)

    def qaoa_state(params):
        gamma_p = float(params[0])
        beta_p = float(params[1])
        psi = psi0 * np.exp(-1j * gamma_p * C_diag)
        psi = apply_x_mixer(psi, beta_p)
        return psi

    def cost_fn(params):
        psi = qaoa_state(params)
        probs = psi.real * psi.real + psi.imag * psi.imag
        return float(np.sum(probs * C_diag))

    x0 = np.array([0.1, 0.1])
    res =minimize(cost_fn, x0, method="COBYLA", options={"maxiter": 20})
    best_params = res.x if (res.x is not None) else x0

    psi_final = qaoa_state(best_params)
    probs = psi_final.real * psi_final.real + psi_final.imag * psi_final.imag
    best_idx = int(np.argmax(probs))
    bitstring = format(best_idx, "0" + str(n) + "b")
    x = np.array([int(b) for b in bitstring], dtype=float)
    value = float(x @ Q @ x)

    print(json.dumps({
        "value": value,
        "instance": {"type": "qubo", "matrix": Q.tolist(),
                     "num_variables": n, "pauli_terms": pauli_terms},
        "bitstring": bitstring,
        "num_qubits": n,
        "qaoa_params": [float(best_params[0]), float(best_params[1])],
        "expected_cost": float(cost_fn(best_params))
    }))


if __name__ == "__main__":
    main()
```



