```python
import os
import json
import numpy as np
from qiskit import QuantumCircuit
from qiskit.quantum_info import Statevector
from scipy.optimize import minimize


def main():
    instance = json.loads(os.environ["SUB_INSTANCE_JSON"])
    block_items = instance.get("block_items") or []
    if block_items:
        n = len(block_items)
    else:
        n = int(instance.get("num_variables", 0))

    if n == 0:
        print(json.dumps({
            "value": 0.0,
            "instance": {"type": "qubo", "matrix": [], "num_variables": 0,
                          "pauli_terms": []},
            "bitstring": "",
            "num_qubits": 0,
        }))
        return

    stmt = np.array([float(it.get("statement_cov", 0.0)) for it in block_items])
    faults = np.array([float(it.get("faults_cov", 0.0)) for it in block_items])
    ecost = np.array([float(it.get("execution_cost", 0.0)) for it in block_items])

    if stmt.size and stmt.max() > 0:
        local_max_stmt = float(stmt.max())
    else:
        local_max_stmt = 1.0
    if faults.size and faults.max() > 0:
        local_max_faults = float(faults.max())
    else:
        local_max_faults = 1.0
    if ecost.size and ecost.max() > 0:
        local_max_cost = float(ecost.max())
    else:
        local_max_cost = 1.0

    max_stmt = float(instance.get("max_stmt", local_max_stmt))
    max_faults = float(instance.get("max_faults", local_max_faults))
    max_cost = float(instance.get("max_cost", local_max_cost))
    if max_stmt <= 0:
        max_stmt = 1.0
    if max_faults <= 0:
        max_faults = 1.0
    if max_cost <= 0:
        max_cost = 1.0

    g = (1.0 / 3.0) * (stmt / max_stmt) \
        + (1.0 / 3.0) * (faults / max_faults) \
        - (1.0 / 3.0) * (ecost / max_cost)

    Q = np.zeros((n, n), dtype=float)
    for i in range(n):
        Q[i, i] = float(-g[i])

    h = -Q.diagonal() / 2.0
    ising_const =float(Q.diagonal().sum() / 2.0)

    if not np.any(np.abs(h) > 1e-15):
        x = np.zeros(n, dtype=float)
        value = float(x @ Q @ x)
        print(json.dumps({
            "value": value,
            "instance": {"type": "qubo", "matrix": Q.tolist(),
                          "num_variables": n, "pauli_terms": [],
                          "ising_const": ising_const},
            "bitstring": "0" * n,
            "num_qubits": n,
            "note": "all-zero block",
        }))
        return

    N = 1 << n
    idx = np.arange(N, dtype=np.int64)
    E = np.zeros(N, dtype=float)
    for i in range(n):
        bits_i = ((idx >> i) & 1).astype(float)
        E += h[i] * (1.0 - 2.0 * bits_i)

    hints = instance.get("qaoa_hints", {})
    if isinstance(hints, dict):
        p_layers = int(hints.get("p_layers", 1))
    else:
        p_layers = 1
    if p_layers < 1:
        p_layers = 1
    if p_layers > 2:
        p_layers = 2

    def build_circuit(params):
        qc = QuantumCircuit(n)
        qc.h(range(n))
        for layer in range(p_layers):
            gamma = float(params[2 * layer])
            beta = float(params[2 * layer + 1])
            for i in range(n):
                if abs(h[i]) > 1e-15:
                    qc.rz(2.0 * gamma * h[i], i)
            for i in range(n):
                qc.rx(2.0 * beta, i)
        return qc

    def cost_fn(params):
        qc = build_circuit(params)
        sv = Statevector(qc)
        probs = np.abs(np.asarray(sv.data)) ** 2
        return float(np.dot(probs, E))

    x0 = np.array([0.1, 0.1] * p_layers, dtype=float)
    res = minimize(cost_fn, x0, method="COBYLA", options={"maxiter": 20})
    if getattr(res, "x", None) is not None:
        best_params = res.x
    else:
        best_params = x0

    qc = build_circuit(best_params)
    sv = Statevector(qc)
    probs = np.abs(np.asarray(sv.data)) ** 2
    best_k = int(np.argmax(probs))

    x_bits = [(best_k>> i) & 1 for i in range(n)]
    x = np.array(x_bits, dtype=float)
    value = float(x @ Q @ x)

    bitstring = "".join(str(x_bits[n - 1 - i]) for i in range(n))

    pauli_terms = []
    for i in range(n):
        if abs(h[i]) < 1e-15:
            continue
        label = ["I"] * n
        label[n - 1 - i] = "Z"
        pauli_terms.append(("".join(label), float(h[i])))

    selected_local_indices = [i for i, b in enumerate(x_bits) if b == 1]
    selected_ids = [block_items[i].get("id", "t" + str(i))
                    for i in selected_local_indices]

    print(json.dumps({
        "value": value,
        "instance": {
            "type": "qubo",
            "matrix": Q.tolist(),
            "num_variables": n,
            "pauli_terms": pauli_terms,
            "ising_const": ising_const,
        },
        "bitstring": bitstring,
        "num_qubits": n,
        "selected_local_indices": selected_local_indices,
        "selected_ids": selected_ids,
        "p_layers": p_layers,
    }))


if __name__ == "__main__":
    main()
```



